867	<script>
868	// === input.js — Racing Game ===
869	// Handles all player input: keyboard (desktop), touch (mobile), gamepad stub.
870	// All functions and state attached to window.R.
871	// Depends on: R.canvas, R.ctx, R.input, R.CONFIG, R.state
872	
873	// ---------------------------------------------------------------------------
874	// Default R.input structure (filled if not already populated by engine-core)
875	// ---------------------------------------------------------------------------
876	
877	R.input = R.input || {};
878	R.input.throttle = R.input.throttle ?? 0;
879	R.input.brake    = R.input.brake    ?? 0;
880	R.input.steer    = R.input.steer    ?? 0;
881	R.input.boost    = R.input.boost    ?? 0;
882	R.input.confirm  = R.input.confirm  ?? false;
883	R.input.pause    = R.input.pause    ?? false;
884	
885	// ---------------------------------------------------------------------------
886	// Internal key-state tracker — holds key down state for continuous actions
887	// ---------------------------------------------------------------------------
888	
889	const _keysDown = {};        // e.code → true/false
890	const _gameKeys = new Set(); // keys we care about (for fast lookup)
891	let   _touchActive = false;  // whether a touch is currently held
892	let   _touchStartX  = 0;
893	let   _touchStartY  = 0;
894	let   _touchStartTime = 0;
895	let   _touchCurrentX = 0;
896	let   _touchCurrentY = 0;
897	let   _touchMoved   = false; // has the finger moved beyond a tap threshold
898	let   _edgeTriggeredConfirm = false;
899	let   _edgeTriggeredPause   = false;
900	let   _gamepadIndex   = -1;  // detected gamepad index, -1 if none
901	let   _gamepadActive  = false;
902	
903	// Tap / swipe thresholds (in px)
904	const TAP_DISTANCE    = 30;  // max movement to count as tap
905	const SWIPE_DISTANCE  = 60;  // min movement to count as swipe
906	const TAP_MAX_TIME    = 300; // ms — max duration for tap
907	
908	// Game keys we intercept with preventDefault
909	const GAME_KEY_CODES = [
910	  'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight',
911	  'KeyW', 'KeyA', 'KeyS', 'KeyD',
912	  'ShiftLeft', 'ShiftRight', 'Space',
913	  'Enter', 'Escape', 'KeyP'
914	];
915	
916	// Build the fast-lookup set
917	GAME_KEY_CODES.forEach(function (c) { _gameKeys.add(c); });
918	
919	// ---------------------------------------------------------------------------
920	// Keyboard state → R.input mapping (called each frame)
921	// ---------------------------------------------------------------------------
922	
923	function _syncKeyboardState() {
924	  // Steering — left takes priority over right when both held
925	  const left  = _keysDown['ArrowLeft']  || _keysDown['KeyA'] || false;
926	  const right = _keysDown['ArrowRight'] || _keysDown['KeyD'] || false;
927	  if (left && !right) {
928	    R.input.steer = -1;
929	  } else if (right && !left) {
930	    R.input.steer = 1;
931	  } else if (left && right) {
932	    R.input.steer = 0; // both held → cancel (rare)
933	  } else {
934	    R.input.steer = 0;
935	  }
936	
937	  // Throttle
938	  R.input.throttle = (_keysDown['ArrowUp'] || _keysDown['KeyW']) ? 1 : 0;
939	
940	  // Brake
941	  R.input.brake = (_keysDown['ArrowDown'] || _keysDown['KeyS']) ? 1 : 0;
942	
943	  // Boost
944	  R.input.boost = (_keysDown['ShiftLeft'] || _keysDown['ShiftRight'] || _keysDown['Space']) ? 1 : 0;
945	}
946	
947	// ---------------------------------------------------------------------------
948	// Touch state → R.input mapping (called each frame)
949	// ---------------------------------------------------------------------------
950	
951	function _syncTouchState() {
952	  if (!_touchActive) {
953	    // No finger down — clear touch-driven input unless keyboard is handling it
954	    return;
955	  }
956	  if (!_touchMoved) {
957	    // Finger hasn't moved enough for a swipe — no steering/throttle/brake yet
958	    return;
959	  }
960	
961	  const dx = _touchCurrentX - _touchStartX;
962	  const dy = _touchCurrentY - _touchStartY;
963	  const absDx = Math.abs(dx);
964	  const absDy = Math.abs(dy);
965	
966	  // Only override if touch actually provides meaningful input
967	  if (absDx < TAP_DISTANCE && absDy < TAP_DISTANCE) return;
968	
969	  // Steer: horizontal position on screen
970	  const halfW = R.canvas.width * 0.5;
971	  if (_touchCurrentX < halfW - 30) {
972	    // Left half → steer left (proportional)
973	    const zone = halfW - 30;
974	    R.input.steer = -Math.min(1, (zone - _touchCurrentX) / zone);
975	  } else if (_touchCurrentX > halfW + 30) {
976	    // Right half → steer right (proportional)
977	    const zone = halfW - 30;
978	    R.input.steer = Math.min(1, (_touchCurrentX - halfW - 30) / zone);
979	  }
980	
981	  // Swipe up → throttle, swipe down → brake (dominant vertical direction)
982	  if (absDy > absDx && absDy > SWIPE_DISTANCE) {
983	    if (dy < 0) {
984	      R.input.throttle = 1;
985	      R.input.brake    = 0;
986	    } else {
987	      R.input.brake    = 1;
988	      R.input.throttle = 0;
989	    }
990	  }
991	}
992	
993	// ---------------------------------------------------------------------------
994	// Gamepad state → R.input mapping (called each frame when gamepad is active)
995	// ---------------------------------------------------------------------------
996	
997	function _syncGamepadState() {
998	  if (!_gamepadActive || _gamepadIndex < 0) return;
999	
1000	  const gamepads = navigator.getGamepads ? navigator.getGamepads() : [];
1001	  const gp = gamepads[_gamepadIndex];
1002	  if (!gp) {
1003	    _gamepadActive = false;
1004	    _gamepadIndex = -1;
1005	    return;
1006	  }
1007	
1008	  // Left stick horizontal → steering (axis 0)
1009	  // Apply a small deadzone to avoid drift
1010	  const rawSteer = gp.axes[0] || 0;
1011	  if (Math.abs(rawSteer) < 0.15) {
1012	    R.input.steer = 0;
1013	  } else {
1014	    R.input.steer = Math.max(-1, Math.min(1, rawSteer));
1015	  }
1016	
1017	  // Right trigger → throttle (axis 5 on standard mapping, 0..1)
1018	  // Left trigger → brake (axis 4 on standard mapping, 0..1)
1019	  // Some controllers map triggers to buttons 6/7 — we handle both
1020	  if (gp.buttons[7] && typeof gp.buttons[7].value === 'number') {
1021	    R.input.throttle = gp.buttons[7].value; // right trigger as button
1022	  } else {
1023	    R.input.throttle = (gp.axes[5] !== undefined) ? (gp.axes[5] + 1) * 0.5 : 0;
1024	  }
1025	  if (gp.buttons[6] && typeof gp.buttons[6].value === 'number') {
1026	    R.input.brake = gp.buttons[6].value; // left trigger as button
1027	  } else {
1028	    R.input.brake = (gp.axes[4] !== undefined) ? (gp.axes[4] + 1) * 0.5 : 0;
1029	  }
1030	
1031	  // A button (index 0) → boost
1032	  R.input.boost = gp.buttons[0] && gp.buttons[0].pressed ? 1 : 0;
1033	
1034	  // Start button (index 9) → pause (edge-triggered)
1035	  if (gp.buttons[9] && gp.buttons[9].pressed) {
1036	    _edgeTriggeredPause = true;
1037	  }
1038	
1039	  // Confirm via A button or Start (edge-triggered in updateInput)
1040	  if (gp.buttons[0] && gp.buttons[0].pressed) {
1041	    _edgeTriggeredConfirm = true;
1042	  }
1043	}
1044	
1045	// ---------------------------------------------------------------------------
1046	// Keyboard event handlers
1047	// ---------------------------------------------------------------------------
1048	
1049	function _onKeyDown(e) {
1050	  if (!_gameKeys.has(e.code)) return; // not a game key — ignore
1051	
1052	  e.preventDefault(); // prevent scrolling / default browser action
1053	
1054	  // Edge-triggered actions (set flag once per press)
1055	  if (e.code === 'Enter') {
1056	    _edgeTriggeredConfirm = true;
1057	    return;
1058	  }
1059	  if (e.code === 'Escape' || e.code === 'KeyP') {
1060	    _edgeTriggeredPause = true;
1061	    return;
1062	  }
1063	
1064	  // Continuous actions — just track key down
1065	  _keysDown[e.code] = true;
1066	}
1067	
1068	function _onKeyUp(e) {
1069	  if (!_gameKeys.has(e.code)) return;
1070	
1071	  e.preventDefault();
1072	
1073	  // Edge-triggered keys don't need up handling
1074	  if (e.code === 'Enter' || e.code === 'Escape' || e.code === 'KeyP') return;
1075	
1076	  _keysDown[e.code] = false;
1077	}
1078	
1079	// ---------------------------------------------------------------------------
1080	// Touch event handlers
1081	// ---------------------------------------------------------------------------
1082	
1083	function _onTouchStart(e) {
1084	  e.preventDefault(); // prevent scrolling / pinch-zoom
1085	
1086	  const t = e.changedTouches[0];
1087	  if (!t) return;
1088	
1089	  _touchActive    = true;
1090	  _touchStartX    = t.clientX;
1091	  _touchStartY    = t.clientY;
1092	  _touchStartTime = Date.now();
1093	  _touchCurrentX  = t.clientX;
1094	  _touchCurrentY  = t.clientY;
1095	  _touchMoved     = false;
1096	
1097	  // Set boost on touch start if it's a quick double-tap pattern (handled per-frame)
1098	}
1099	
1100	function _onTouchMove(e) {
1101	  e.preventDefault();
1102	
1103	  if (!_touchActive) return;
1104	
1105	  const t = e.changedTouches[0];
1106	  if (!t) return;
1107	
1108	  const prevX = _touchCurrentX;
1109	  const prevY = _touchCurrentY;
1110	  _touchCurrentX = t.clientX;
1111	  _touchCurrentY = t.clientY;
1112	
1113	  // Mark as moved if beyond tap threshold
1114	  const totalDx = _touchCurrentX - _touchStartX;
1115	  const totalDy = _touchCurrentY - _touchStartY;
1116	  if (Math.abs(totalDx) > TAP_DISTANCE || Math.abs(totalDy) > TAP_DISTANCE) {
1117	    _touchMoved = true;
1118	  }
1119	}
1120	
1121	function _onTouchEnd(e) {
1122	  e.preventDefault();
1123	
1124	  if (!_touchActive) return;
1125	
1126	  const t = e.changedTouches[0];
1127	  if (!t) { _resetTouch(); return; }
1128	
1129	  const endX = t.clientX;
1130	  const endY = t.clientY;
1131	  const dx   = endX - _touchStartX;
1132	  const dy   = endY - _touchStartY;
1133	  const dist = Math.sqrt(dx * dx + dy * dy);
1134	  const elapsed = Date.now() - _touchStartTime;
1135	
1136	  // Tap detection: small movement + short duration
1137	  if (dist < TAP_DISTANCE && elapsed < TAP_MAX_TIME) {
1138	    // Tap center 40% of screen → confirm
1139	    const centerX = R.canvas.width  * 0.5;
1140	    const centerY = R.canvas.height * 0.5;
1141	    const tapRadius = R.canvas.width * 0.2; // center 40% in width
1142	    if (Math.abs(endX - centerX) < tapRadius && Math.abs(endY - centerY) < tapRadius) {
1143	      _edgeTriggeredConfirm = true;
1144	    }
1145	  }
1146	
1147	  _resetTouch();
1148	}
1149	
1150	function _onTouchCancel(e) {
1151	  _resetTouch();
1152	}
1153	
1154	function _resetTouch() {
1155	  _touchActive    = false;
1156	  _touchStartX    = 0;
1157	  _touchStartY    = 0;
1158	  _touchStartTime = 0;
1159	  _touchCurrentX  = 0;
1160	  _touchCurrentY  = 0;
1161	  _touchMoved     = false;
1162	}
1163	
1164	// ---------------------------------------------------------------------------
1165	// Public API
1166	// ---------------------------------------------------------------------------
1167	
1168	/**
1169	 * R.initInput()
1170	 * Bind all input event listeners (keyboard, touch).
1171	 * Safe to call multiple times — removes previous listeners first.
1172	 * Call once during game initialization.
1173	 */
1174	R.initInput = function () {
1175	  // Remove old listeners if re-initializing
1176	  if (R._inputListenersBound) {
1177	    R.destroyInput();
1178	  }
1179	
1180	  // Keyboard
1181	  window.addEventListener('keydown', _onKeyDown, { passive: false });
1182	  window.addEventListener('keyup',   _onKeyUp,   { passive: false });
1183	
1184	  // Touch (only if touch-capable, but safe to bind regardless)
1185	  const cvs = R.canvas;
1186	  if (cvs) {
1187	    cvs.addEventListener('touchstart', _onTouchStart,  { passive: false });
1188	    cvs.addEventListener('touchmove',  _onTouchMove,   { passive: false });
1189	    cvs.addEventListener('touchend',   _onTouchEnd,    { passive: false });
1190	    cvs.addEventListener('touchcancel',_onTouchCancel, { passive: false });
1191	  }
1192	
1193	  // Visibility change — clear all keys if tab loses focus
1194	  window.addEventListener('blur', function () {
1195	    // Clear all held keys on blur to prevent stuck inputs
1196	    for (var k in _keysDown) {
1197	      if (_keysDown.hasOwnProperty(k)) _keysDown[k] = false;
1198	    }
1199	    _resetTouch();
1200	    R.input.throttle = 0;
1201	    R.input.brake    = 0;
1202	    R.input.steer    = 0;
1203	    R.input.boost    = 0;
1204	  });
1205	
1206	  R._inputListenersBound = true;
1207	};
1208	
1209	/**
1210	 * R.destroyInput()
1211	 * Remove all input event listeners. Call before shutdown or re-init.
1212	 */
1213	R.destroyInput = function () {
1214	  window.removeEventListener('keydown', _onKeyDown);
1215	  window.removeEventListener('keyup',   _onKeyUp);
1216	
1217	  const cvs = R.canvas;
1218	  if (cvs) {
1219	    cvs.removeEventListener('touchstart',  _onTouchStart);
1220	    cvs.removeEventListener('touchmove',   _onTouchMove);
1221	    cvs.removeEventListener('touchend',    _onTouchEnd);
1222	    cvs.removeEventListener('touchcancel', _onTouchCancel);
1223	  }
1224	
1225	  R._inputListenersBound = false;
1226	};
1227	
1228	/**
1229	 * R.updateInput()
1230	 * Called every frame. Syncs raw input state to R.input and clears
1231	 * edge-triggered flags that were consumed.
1232	 */
1233	R.updateInput = function () {
1234	  // 1. Sync keyboard continuous state
1235	  _syncKeyboardState();
1236	
1237	  // 2. Sync touch state
1238	  _syncTouchState();
1239	
1240	  // 3. Sync gamepad (if active)
1241	  if (_gamepadActive) {
1242	    _syncGamepadState();
1243	  }
1244	
1245	  // 4. Edge-triggered flags — transfer from internal to R.input
1246	  //    These are set by event handlers and consumed once by the state machine.
1247	  //    We do NOT reset them here — they persist until consumeConfirm/consumePause
1248	  //    is called. But we must NOT double-set them either.
1249	  if (_edgeTriggeredConfirm) {
1250	    R.input.confirm = true;
1251	    _edgeTriggeredConfirm = false;
1252	  }
1253	  if (_edgeTriggeredPause) {
1254	    R.input.pause = true;
1255	    _edgeTriggeredPause = false;
1256	  }
1257	};
1258	
1259	/**
1260	 * R.consumeConfirm()
1261	 * Called by the state machine after reading R.input.confirm.
1262	 * Resets the flag so it fires only once per press.
1263	 */
1264	R.consumeConfirm = function () {
1265	  R.input.confirm = false;
1266	};
1267	
1268	/**
1269	 * R.consumePause()
1270	 * Called by the state machine after reading R.input.pause.
1271	 * Resets the flag so it fires only once per press.
1272	 */
1273	R.consumePause = function () {
1274	  R.input.pause = false;
1275	};
1276	
1277	// ---------------------------------------------------------------------------
1278	// Gamepad support (optional stub)
1279	// ---------------------------------------------------------------------------
1280	
1281	/**
1282	 * R.initGamepad()
1283	 * Detect the first connected gamepad and begin polling.
1284	 * Gamepad state is read each frame inside updateInput() via _syncGamepadState().
1285	 * Re-checks for gamepad connection on every call (safe to call each frame
1286	 * or on-demand).
1287	 *
1288	 * Mapping (standard):
1289	 *   Left stick X  → steer
1290	 *   Right trigger → throttle
1291	 *   Left trigger  → brake
1292	 *   A button      → boost
1293	 *   Start button  → pause
1294	 */
1295	R.initGamepad = function () {
1296	  // If we already have an active gamepad, verify it's still connected
1297	  if (_gamepadActive && _gamepadIndex >= 0) {
1298	    var gamepads = navigator.getGamepads ? navigator.getGamepads() : [];
1299	    if (gamepads[_gamepadIndex]) return; // still connected
1300	    // Disconnected — fall through to re-detect
1301	    _gamepadActive = false;
1302	    _gamepadIndex = -1;
1303	  }
1304	
1305	  // Detect first connected gamepad
1306	  var gamepads = navigator.getGamepads ? navigator.getGamepads() : [];
1307	  for (var i = 0; i < gamepads.length; i++) {
1308	    if (gamepads[i] && gamepads[i].connected) {
1309	      _gamepadIndex = i;
1310	      _gamepadActive = true;
1311	      return;
1312	    }
1313	  }
1314	
1315	  // No gamepad found
1316	  _gamepadIndex = -1;
1317	  _gamepadActive = false;
1318	};
1319	
1320	/**
1321	 * R.isGamepadActive()
1322	 * Returns true if a gamepad is currently detected and being polled.
1323	 * @returns {boolean}
1324	 */
1325	R.isGamepadActive = function () {
1326	  return _gamepadActive;
1327	};
1328	
1329	/**
1330	 * R.refreshGamepad()
1331	 * Force a re-scan for newly connected/disconnected gamepads.
1332	 * (Alias for initGamepad — same logic.)
1333	 */
1334	R.refreshGamepad = R.initGamepad;
1335	
1336	// ---------------------------------------------------------------------------
1337	// Additional utility: R.getInputDebugInfo()
1338	// Returns a snapshot of current input state for debugging / HUD overlay.
1339	// ---------------------------------------------------------------------------
1340	
1341	/**
1342	 * R.getInputDebugInfo()
1343	 * Returns an object with current raw input state for debug display.
1344	 * @returns {{ throttle: number, brake: number, steer: number, boost: number,
1345	 *             confirm: boolean, pause: boolean, touchActive: boolean,
1346	 *             gamepadActive: boolean, keysHeld: string[] }}
1347	 */
1348	R.getInputDebugInfo = function () {
1349	  var held = [];
1350	  for (var k in _keysDown) {
1351	    if (_keysDown.hasOwnProperty(k) && _keysDown[k]) held.push(k);
1352	  }
1353	  return {
1354	    throttle:      R.input.throttle,
1355	    brake:         R.input.brake,
1356	    steer:         R.input.steer,
1357	    boost:         R.input.boost,
1358	    confirm:       R.input.confirm,
1359	    pause:         R.input.pause,
1360	    touchActive:   _touchActive,
1361	    gamepadActive: _gamepadActive,
1362	    keysHeld:      held
1363	  };
1364	};
1365	
1366	// ---------------------------------------------------------------------------
1367	// Exported symbols (attached to window.R):
1368	//   R.initInput()
1369	//   R.destroyInput()
1370	//   R.updateInput()
1371	//   R.consumeConfirm()
1372	//   R.consumePause()
1373	//   R.initGamepad()
1374	//   R.isGamepadActive()
1375	//   R.refreshGamepad()
1376	//   R.getInputDebugInfo()
1377	// ---------------------------------------------------------------------------
1378	</script>

2365	<script>
2366	// === player.js — Racing Game ===
2367	// Player car: physics simulation, rendering, checkpoint/lap logic.
2368	// All functions attach to window.R. Assumes R.CONFIG, R.canvas, R.ctx,
2369	// R.input, R.camera, R.track, and R.state already exist.
2370	
2371	/* ==========================================================================
2372	   CONFIG defaults (merged into R.CONFIG if keys are missing)
2373	   ========================================================================== */
2374	(function ensurePlayerConfig() {
2375	  const defaults = {
2376	
2377	    // ── Car physics ──────────────────────────────────────────────────
2378	    MAX_SPEED:           12,        // px/frame at 60 fps (~720 px/s)
2379	    ACCELERATION:        0.08,      // speed += accel * dt * 60
2380	    BRAKING:             0.14,      // speed -= brake * dt * 60
2381	    FRICTION:            0.985,     // multiplicative per-frame drag
2382	    HANDLING:            0.045,     // steer sensitivity
2383	    MAX_STEER:           0.6,       // radians, clamp
2384	    STEER_CENTER_RATE:   0.85,      // per-frame self-centering
2385	    DRIFT_FACTOR:        0.92,      // forward friction while drifting
2386	    DRIFT_THRESHOLD:     0.15,      // drift magnitude to trigger
2387	    OFFROAD_FRICTION:    0.92,      // multiplicative when off track
2388	    BOOST_MULTIPLIER:    1.6,       // speed multiplier during boost
2389	    BOOST_DURATION:      1.5,       // seconds
2390	    BOOST_COOLDOWN:      3.0,       // seconds
2391	
2392	    // ── Car dimensions (pixels in world space) ───────────────────────
2393	    CAR_LENGTH:          48,
2394	    CAR_WIDTH:           24,
2395	    WHEELBASE:           30,        // axle-to-axle distance
2396	    WHEEL_WIDTH:         7,
2397	    WHEEL_LENGTH:        12,
2398	
2399	    // ── Rendering ────────────────────────────────────────────────────
2400	    SHADOW_OFFSET_X:     4,
2401	    SHADOW_OFFSET_Y:     2,
2402	    SHADOW_ALPHA:        0.35,
2403	    WINDSHIELD_RATIO:    0.22,      // portion of car length
2404	    REAR_WINDOW_RATIO:   0.18,
2405	    DOOR_LINE_OFFSET:    0.38,      // door gap from front
2406	    STRIPE_WIDTH:        4,
2407	    EXHAUST_BASE_WIDTH:  8,
2408	    EXHAUST_LENGTH:      14,
2409	    DRIFT_MARK_LIFETIME: 0.6,       // seconds visible
2410	    DRIFT_MARK_SPACING:  5,         // px between marks
2411	
2412	    // ── Checkpoints ──────────────────────────────────────────────────
2413	    CHECKPOINT_PROXIMITY: 60,       // px — how close counts as "passed"
2414	    TOTAL_LAPS:          3,
2415	  };
2416	
2417	  R.CONFIG = R.CONFIG || {};
2418	  for (const k in defaults) {
2419	    if (!(k in R.CONFIG)) R.CONFIG[k] = defaults[k];
2420	  }
2421	})();
2422	
2423	/* ==========================================================================
2424	   DRIFT MARK POOL — pre-allocated circular buffer
2425	   ========================================================================== */
2426	const DRIFT_MARK_CAPACITY = 80;
2427	const driftMarks = new Array(DRIFT_MARK_CAPACITY);
2428	for (let i = 0; i < DRIFT_MARK_CAPACITY; i++) {
2429	  driftMarks[i] = { x: 0, y: 0, alpha: 0, age: 0, alive: false };
2430	}
2431	let driftMarkWriteIdx = 0;
2432	
2433	function spawnDriftMark(x, y) {
2434	  const m = driftMarks[driftMarkWriteIdx];
2435	  m.x = x;
2436	  m.y = y;
2437	  m.alpha = 0.55;
2438	  m.age = 0;
2439	  m.alive = true;
