2550	/* ==========================================================================
2551	   R.updatePlayer(dt) — Full car physics simulation
2552	   dt = delta time in seconds (unscaled)
2553	   ========================================================================== */
2554	R.updatePlayer = function updatePlayer(dt) {
2555	  const p  = R.player;
2556	  if (!p || p.finished) return;
2557	
2558	  const cfg  = R.CONFIG;
2559	  const inp  = R.input;
2560	
2561	  // Clamp dt to avoid huge jumps (tab-away recovery)
2562	  const dtClamped = Math.min(dt, 0.05);
2563	  // Scale factor: physics tuned at 60 fps, so multiply by dt*60
2564	  const f = dtClamped * 60;
2565	
2566	  // ── 1. STEERING ──────────────────────────────────────────────────
2567	  const steerInput = inp.steer || 0;               // -1..0..1
2568	
2569	  // Speed-sensitive steering (tighter at low speed, wider at high)
2570	  const speedRatio = p.speed / p.maxSpeed;
2571	  const steerResponse = cfg.HANDLING * (1 + speedRatio * 0.5);
2572	  p.steerAngle += steerInput * steerResponse * f;
2573	
2574	  // Self-centering (stronger when no input)
2575	  if (Math.abs(steerInput) < 0.05) {
2576	    p.steerAngle *= Math.pow(cfg.STEER_CENTER_RATE, f);
2577	  } else {
2578	    p.steerAngle *= Math.pow(cfg.STEER_CENTER_RATE * 0.97, f);
2579	  }
2580	
2581	  // Clamp
2582	  if (p.steerAngle > cfg.MAX_STEER) p.steerAngle = cfg.MAX_STEER;
2583	  if (p.steerAngle < -cfg.MAX_STEER) p.steerAngle = -cfg.MAX_STEER;
2584	
2585	  // ── 2. ACCELERATION / BRAKING ────────────────────────────────────
2586	  const throttle = inp.throttle || 0;
2587	  const brake    = inp.brake    || 0;
2588	  const boost    = inp.boost    || 0;
2589	
2590	  // Boost activation
2591	  if (boost && !p.boosting && p.boostCooldown <= 0 && p.speed > 0.5) {
2592	    p.boosting     = true;
2593	    p.boostTimer   = cfg.BOOST_DURATION;
2594	    p.boostCooldown = cfg.BOOST_COOLDOWN + cfg.BOOST_DURATION;
2595	  }
2596	
2597	  // Boost timer
2598	  if (p.boosting) {
2599	    p.boostTimer -= dt;
2600	    if (p.boostTimer <= 0) {
2601	      p.boosting   = false;
2602	      p.boostTimer = 0;
2603	    }
2604	  }
2605	
2606	  // Boost cooldown
2607	  if (p.boostCooldown > 0 && !p.boosting) {
2608	    p.boostCooldown -= dt;
2609	    if (p.boostCooldown < 0) p.boostCooldown = 0;
2610	  }
2611	
2612	  // Apply acceleration
2613	  if (throttle && !brake) {
2614	    let accel = p.acceleration * f;
2615	    if (p.boosting) accel *= cfg.BOOST_MULTIPLIER;
2616	    p.speed += accel;
2617	
2618	    // Low-speed extra torque for startup feel
2619	    if (p.speed < 1.0) {
2620	      p.speed += accel * 0.5;
2621	    }
2622	  }
2623	
2624	  if (brake) {
2625	    p.speed -= p.braking * f;
2626	  }
2627	
2628	  // Friction (natural deceleration)
2629	  p.speed *= Math.pow(cfg.FRICTION, f);
2630	
2631	  // Clamp speed (allow slight overshoot from boost)
2632	  const maxNow = p.boosting ? p.maxSpeed * cfg.BOOST_MULTIPLIER : p.maxSpeed;
2633	  if (p.speed < 0)    p.speed = 0;
2634	  if (p.speed > maxNow) p.speed = maxNow;
2635	
2636	  // ── 3. DRIFT ─────────────────────────────────────────────────────
2637	  const lateralForce = p.speed * p.steerAngle * 0.3 * f;
2638	  p.driftFactor += (lateralForce - p.driftFactor) * 0.1 * f;
2639	  const driftMagnitude = Math.abs(p.driftFactor);
2640	  const wasDrifting = p.isDrifting;
2641	  p.isDrifting = driftMagnitude > cfg.DRIFT_THRESHOLD;
2642	
2643	  // ── 4. POSITION UPDATE ───────────────────────────────────────────
2644	  const effectiveAngle = p.angle + p.driftFactor * 0.5;
2645	  const forwardFriction = p.isDrifting
2646	    ? Math.pow(cfg.DRIFT_FACTOR, f)
2647	    : 1.0;
2648	
2649	  p.x += Math.cos(p.angle) * p.speed * Math.cos(p.driftFactor) * forwardFriction * f;
2650	  p.y += Math.sin(p.angle) * p.speed * Math.cos(p.driftFactor) * forwardFriction * f;
2651	  p.angle += p.steerAngle * p.speed * 0.03 * f;
2652	
2653	  // Keep angle in [0, 2π)
2654	  while (p.angle < 0)            p.angle += Math.PI * 2;
2655	  while (p.angle >= Math.PI * 2) p.angle -= Math.PI * 2;
2656	
2657	  // Accumulate wheel rotation (for visual)
2658	  p.wheelRot += p.speed * 0.06 * f;
2659	
2660	  // ── 5. TRACK CHECK ───────────────────────────────────────────────
2661	  if (R.isOnTrack && typeof R.isOnTrack === 'function') {
2662	    if (!R.isOnTrack(p.x, p.z)) {
2663	      p.speed *= Math.pow(cfg.OFFROAD_FRICTION, f);
2664	    }
2665	  }
2666	
2667	  // ── 6. LAP / CHECKPOINT LOGIC ────────────────────────────────────
2668	  if (R.track && R.track.segments && R.track.segments.length) {
2669	    const segs = R.track.segments;
2670	    const totalCheckpoints = segs.length;
2671	
2672	    // Current checkpoint target
2673	    const targetSeg = segs[p.checkpointIdx % totalCheckpoints];
2674	    if (targetSeg) {
2675	      const dx = p.x - (targetSeg.worldX || 0);
2676	      const dy = p.y - (targetSeg.worldY || 0);
2677	      const dist = Math.sqrt(dx * dx + dy * dy);
2678	
2679	      if (dist < cfg.CHECKPOINT_PROXIMITY) {
2680	        p.checkpointIdx++;
2681	
2682	        // Completed a full lap?
2683	        if (p.checkpointIdx >= totalCheckpoints) {
2684	          p.lap++;
2685	          p.checkpointIdx = 0;
2686	
2687	          if (p.lap >= cfg.TOTAL_LAPS) {
2688	            p.finished = true;
2689	            p.speed = 0;
2690	            R.state.phase = 'finished';
2691	          }
2692	        }
2693	      }
2694	    }
2695	  }
2696	
2697	  // ── 7. Store z as total distance traveled ────────────────────────
2698	  p.z += p.speed * f;
2699	
2700	  // ── 8. Drift marks (spawn every few pixels when drifting) ────────
2701	  if (p.isDrifting && p.speed > 1.0) {
2702	    const rearX = p.x - Math.cos(p.angle) * cfg.CAR_LENGTH * 0.4;
2703	    const rearY = p.y - Math.sin(p.angle) * cfg.CAR_LENGTH * 0.4;
2704	    const perpX = Math.cos(p.angle + Math.PI / 2);
2705	    const perpY = Math.sin(p.angle + Math.PI / 2);
2706	
2707	    const trackOffset = cfg.CAR_WIDTH * 0.35;
2708	    // Left rear
2709	    spawnDriftMark(
2710	      rearX + perpX * trackOffset,
2711	      rearY + perpY * trackOffset
2712	    );
2713	    // Right rear
2714	    spawnDriftMark(
2715	      rearX - perpX * trackOffset,
2716	      rearY - perpY * trackOffset
2717	    );
2718	  }
2719	
2720	  // ── 9. Exhaust particles ─────────────────────────────────────────
2721	  if (throttle && p.speed > 0.3) {
2722	    const rearX = p.x - Math.cos(p.angle) * cfg.CAR_LENGTH * 0.5;
2723	    const rearY = p.y - Math.sin(p.angle) * cfg.CAR_LENGTH * 0.5;
2724	    // Per-tick rate: more particles at higher speed / boost
2725	    const rate = p.boosting ? 0.55 : 0.3;
2726	    if (Math.random() < rate * f) {
2727	      spawnExhaustParticle(rearX, rearY, p.angle);
2728	    }
2729	  }
2730	
2731	  // ── 10. Update drift marks (age / fade) ──────────────────────────
2732	  for (let i = 0; i < DRIFT_MARK_CAPACITY; i++) {
2733	    const m = driftMarks[i];
2734	    if (!m.alive) continue;
2735	    m.age += dt;
2736	    if (m.age > cfg.DRIFT_MARK_LIFETIME) {
2737	      m.alive = false;
2738	    } else {
2739	      m.alpha = 0.55 * (1 - m.age / cfg.DRIFT_MARK_LIFETIME);
2740	    }
2741	  }
2742	
2743	  // ── 11. Update exhaust particles ─────────────────────────────────
2744	  for (let i = 0; i < EXHAUST_CAPACITY; i++) {
2745	    const ep = exhaustParticles[i];
2746	    if (!ep.alive) continue;
2747	    ep.life -= dt;
2748	    if (ep.life <= 0) {
2749	      ep.alive = false;
2750	    } else {
2751	      ep.x += ep.vx * f;
2752	      ep.y += ep.vy * f;
2753	    }
2754	  }
2755	
2756	  // ── 12. Update bounce markers ────────────────────────────────────
2757	  for (let i = 0; i < BOUNCE_CAPACITY; i++) {
2758	    const bm = bounceMarkers[i];
2759	    if (!bm.alive) continue;
2760	    bm.alpha -= dt * 2.5;
2761	    bm.radius += dt * 60;
2762	    if (bm.alpha <= 0) bm.alive = false;
2763	  }
