2887	  ctx.lineTo(wsRear * 0.7 + wsFront * 0.3,  -carHalfW * 0.55);
2888	  ctx.lineTo(wsRear * 0.7 + wsFront * 0.3,  -carHalfW * 0.15);
2889	  ctx.closePath();
2890	  ctx.fill();
2891	
2892	  // ── 4. REAR WINDOW ───────────────────────────────────────────────
2893	  const rwFront = -carLen * 0.5 + carLen * cfg.REAR_WINDOW_RATIO;
2894	  const rwRear  = -carLen * 0.5 + carLen * 0.05;
2895	  ctx.fillStyle = 'rgba(20, 35, 55, 0.6)';
2896	  ctx.beginPath();
2897	  ctx.moveTo(rwRear,  -carHalfW * 0.82);
2898	  ctx.lineTo(rwFront, -carHalfW * 0.85);
2899	  ctx.lineTo(rwFront,  carHalfW * 0.85);
2900	  ctx.lineTo(rwRear,   carHalfW * 0.82);
