3317	/**
3318	 * Draw a rounded rectangle path on the current context.
3319	 * @param {CanvasRenderingContext2D} ctx
3320	 * @param {number} x - left
3321	 * @param {number} y - top
3322	 * @param {number} w - width
3323	 * @param {number} h - height
3324	 * @param {number} r - corner radius
3325	 */
3326	function roundedRect(ctx, x, y, w, h, r) {
3327	  r = Math.min(r, w / 2, h / 2);
3328	  ctx.moveTo(x + r, y);
3329	  ctx.lineTo(x + w - r, y);
3330	  ctx.arcTo(x + w, y, x + w, y + r, r);
3331	  ctx.lineTo(x + w, y + h - r);
3332	  ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
3333	  ctx.lineTo(x + r, y + h);
3334	  ctx.arcTo(x, y + h, x, y + h - r, r);
3335	  ctx.lineTo(x, y + r);
3336	  ctx.arcTo(x, y, x + r, y, r);
3337	  ctx.closePath();
3338	}
